import UIKit

/// iOS implementation of `DeviceInfoApi` (the protocol is generated by `rux build` from the
/// plugin's Rust declaration). Registered by `[package.metadata.rux.native]`.
final class DeviceInfoApiImpl: DeviceInfoApi {
    func info() throws -> DeviceInfo {
        let device = UIDevice.current
        #if targetEnvironment(simulator)
        let isSimulator = true
        let model = ProcessInfo.processInfo.environment["SIMULATOR_MODEL_IDENTIFIER"] ?? device.model
        #else
        let isSimulator = false
        let model = Self.machine() ?? device.model
        #endif
        return DeviceInfo(
            platform: device.systemName,
            osVersion: device.systemVersion,
            model: model,
            isSimulator: isSimulator
        )
    }

    func battery(completion: @escaping (Result<Battery, Error>) -> Void) {
        // Async: answer later (UIDevice must be used on the main thread).
        DispatchQueue.main.async {
            let device = UIDevice.current
            device.isBatteryMonitoringEnabled = true
            let level = device.batteryLevel < 0 ? nil : Int32((device.batteryLevel * 100).rounded())
            let state: BatteryState
            switch device.batteryState {
            case .charging: state = .charging
            case .unplugged: state = .discharging
            case .full: state = .full
            default: state = .unknown
            }
            completion(.success(Battery(level: level, state: state)))
        }
    }

    /// Hardware identifier, e.g. `iPhone17,3`.
    private static func machine() -> String? {
        var info = utsname()
        uname(&info)
        return withUnsafeBytes(of: info.machine) { buf in
            String(bytes: buf.prefix { $0 != 0 }, encoding: .utf8)
        }
    }
}
